const p={title:"Executive Leadership",overview:"Executive leadership encompasses C-suite roles, directors, and senior management positions that shape organizational strategy, culture, and impact. Core responsibilities include strategic planning, stakeholder management, team building, and driving results. The path to executive roles typically involves 10–20+ years of progressive responsibility.",roles:[{title:"Chief Executive Officer (CEO)",desc:"The highest-ranking executive who sets organizational vision, strategy, and culture. Reports to the board and is ultimately responsible for company performance."},{title:"Chief Operating Officer (COO)",desc:"Oversees day-to-day operations, implements strategy, optimizes processes, and manages operational teams."},{title:"Director / Vice President",desc:"Mid-level executives who lead functional areas (e.g., VP of Sales, VP of Product, Director of Operations) and report to C-suite."},{title:"Manager / Team Lead",desc:"Entry point to leadership roles. Builds and develops teams, sets performance expectations, and translates strategy into action."}],education:["MBA (highly valued)","Bachelor in Business, Economics, or related field","Executive Leadership Certificates","Advanced degrees in specialized areas (e.g., MBA Finance)"],skills:["Strategic thinking","Emotional intelligence","Decision-making under uncertainty","Team building","Communication","Financial acumen","Change management"],salary:{entry:"$60,000 - $120,000",mid:"$110,000 - $250,000",senior:"$200,000 - $500,000+"},tips:"Take on stretch projects early in your career; seek mentors in senior roles; develop financial literacy and P&L understanding; join leadership development programs; read business classics (Good to Great, Leaders Eat Last); present in front of large groups to build executive presence; pursue an MBA if aligned with your goals; build a strong professional network across industries.",discussion:["What does leadership mean to you?","Describe your leadership philosophy and key principles.","How do you make strategic decisions?","What is your approach to building and developing teams?","How do you handle conflict or difficult conversations?","Tell us about a major initiative you led and lessons learned.","How do you stay informed and anticipate market changes?","What mentors or leaders have shaped you?","How do you balance financial results with people and culture?","What is your vision for the future of your industry?","How do you drive innovation and empower others?","What advice would you give aspiring leaders?","How do you navigate complex stakeholder dynamics?"],reflection:["What leadership qualities do I want to develop?","Who are my leadership role models and why?","What kind of organization culture do I want to build?"]},m={title:"Tech",overview:"Tech encompasses software engineering, IT operations, cybersecurity, data science, AI/ML, and infrastructure roles. The sector evolves rapidly with new languages, frameworks, and paradigms. Strong technical foundation + continuous learning is essential. Remote work and flexible arrangements are common.",roles:[{title:"Software Engineer / Developer",desc:"Designs, codes, tests, and maintains software applications. Specializations include frontend, backend, full-stack, mobile, and embedded systems."},{title:"Data Scientist / Analyst",desc:"Extracts insights from data using statistics, machine learning, and programming. Focuses on informed decision-making."},{title:"DevOps / Cloud Engineer",desc:"Manages infrastructure, deployment pipelines, cloud services, and system reliability."},{title:"Product Manager (Tech)",desc:"Bridges engineering and business. Defines product strategy, prioritizes features, and drives product roadmap."}],education:["Bachelor in Computer Science, Engineering, or related field","Coding bootcamps (12-16 weeks)","Certifications (AWS, Google Cloud, CompTIA)","Self-taught with strong portfolio"],skills:["Programming languages (Python, JavaScript, Java, Go)","System design & architecture","Problem-solving","Collaboration","Testing & debugging","Cloud platforms","Version control (Git)"],salary:{entry:"$55,000 - $110,000",mid:"$130,000 - $200,000",senior:"$140,000 - $350,000+"},tips:"Build a portfolio of projects on GitHub; contribute to open-source; learn at least 2 programming languages deeply; practice coding interviews (LeetCode, HackerRank); stay current with tech trends (podcasts, blogs, conferences); pursue internships or entry-level roles at startups or FAANG; consider cloud certifications; join tech communities and hackathons.",discussion:["What drew you to a career in tech?","Describe a challenging technical problem you solved.","What is your tech stack and why?","How do you stay updated with the latest technologies?","Tell us about a project you are proud of.","How do you approach system design and scalability?","What is the role of collaboration in engineering?","How do you handle technical debt and refactoring?","What are emerging trends in your tech area?","What advice would you give aspiring engineers?","How do you transition from junior to senior engineer?","What is your approach to mentoring junior developers?","How do you balance speed and quality in development?"],reflection:["What problem do I want to solve with code?","What languages or frameworks excite me most?","How do I stay current in a rapidly changing field?"]},y={title:"Healthcare",overview:"Healthcare spans clinical roles (doctors, nurses, therapists), research, public health, healthcare management, and health tech. Core focus: improving patient outcomes, advancing medical science, and increasing access. High-stakes, meaningful work with strong job security.",roles:[{title:"Physician / Doctor",desc:"Diagnoses and treats patients. Specialties vary widely (cardiology, pediatrics, psychiatry, etc.). Requires medical degree and licensing."},{title:"Nurse / Registered Nurse",desc:"Provides patient care, administers medications, and supports physicians. Core role in hospitals and clinics."},{title:"Public Health Professional",desc:"Focuses on population health, disease prevention, epidemiology, and health policy."},{title:"Healthcare Administrator / Manager",desc:"Manages hospital/clinic operations, budgets, staff, and strategic planning."}],education:["MD (Doctor of Medicine) or DO (Doctor of Osteopathic Medicine)","RN (Registered Nurse) - Associate or Bachelor","MPH (Master of Public Health)","Nursing specialization certifications"],skills:["Clinical assessment","Communication with patients","Empathy & compassion","Attention to detail","Time management","Teamwork","Continuous learning"],salary:{entry:"$60,000 - $100,000",mid:"$100,000 - $180,000",senior:"$110,000 - $300,000+"},tips:"Volunteer in hospitals, clinics, or nursing homes early; shadow healthcare professionals; maintain strong GPA for medical school prerequisites; take MCAT/NCLEX prep seriously; join pre-med or nursing clubs; research specialties that align with your values; consider gap year for life experience; build resilience and stress management skills.",discussion:["What inspired your healthcare career?","Describe your daily responsibilities and typical day.","What specialization or focus area did you choose and why?","How do you maintain work-life balance in healthcare?","Tell us about a patient or case that impacted you.","What are the biggest challenges in healthcare today?","How do you stay current with medical advancements?","How has healthcare evolved during your career?","What role does technology play in your work?","What advice would you give aspiring healthcare professionals?","How do you approach patient communication and empathy?","What is your philosophy on preventive vs. acute care?","How do you handle difficult or emotional situations?"],reflection:["Why do I want to work in healthcare?","What patient population resonates with me?","How do I handle the emotional weight of this work?"]},g={title:"Legal",overview:"Legal careers span litigation, corporate law, public interest, policy, and in-house counsel roles. Lawyers serve as advisors, advocates, and change-makers. Requires law school, bar exam, and strong analytical + persuasion skills.",roles:[{title:"Litigation Attorney",desc:"Represents clients in legal disputes, prepares cases, and argues in court. Works in law firms or corporations."},{title:"Corporate Counsel",desc:"Provides legal advice to businesses on contracts, compliance, M&A, and strategy."},{title:"Public Interest Lawyer",desc:"Works on civil rights, criminal defense, immigration, or nonprofit matters. Often lower pay but high impact."},{title:"Policy Advocate / Lobbyist",desc:"Influences legislation and policy at federal, state, or local levels."}],education:["Juris Doctor (JD) from accredited law school","Pass bar exam in target state","Specialization certificates in areas like intellectual property or international law"],skills:["Legal research & writing","Argumentation & persuasion","Attention to detail","Client communication","Critical thinking","Negotiation","Time management"],salary:{entry:"$70,000 - $120,000",mid:"$130,000 - $250,000",senior:"$150,000 - $400,000+"},tips:"Maintain strong academic record; volunteer with legal aid organizations or courts; intern at law firms or nonprofits; participate in moot court and debate; build a network in legal circles; prepare thoroughly for LSAT; choose law schools strategically (target market); build writing skills early; consider public interest loan forgiveness programs.",discussion:["What inspired your legal career?","Describe your primary practice area and cases you have handled.","What is your approach to client relationships?","Tell us about a landmark case or precedent in your field.","How has law practice changed in your career?","What are current legal trends or challenges?","How do you balance advocacy with ethics?","Tell us about a client or case that shaped you.","What is your philosophy on access to justice?","What advice would you give aspiring lawyers?","How do you navigate complex legal research?","What soft skills are critical for lawyers?","How do you continue learning and stay current?"],reflection:["What area of law excites me most?","How do I want to use law to create impact?","Am I called to serve people or corporations?"]},f={title:"Banking & Finance",overview:"Finance covers investment banking, corporate finance, asset management, trading, financial planning, and fintech. The sector drives capital allocation and economic growth. Attracts analytical, ambitious professionals. Strong quantitative skills valued.",roles:[{title:"Investment Banker",desc:"Advises corporations on M&A, capital raises, and valuations. High pressure, fast-paced, well-compensated."},{title:"Financial Analyst",desc:"Analyzes financial data, builds models, and provides investment recommendations."},{title:"Wealth Manager / Financial Advisor",desc:"Manages client portfolios and provides personalized financial planning."},{title:"Trader",desc:"Executes buy/sell decisions in markets. Driven by market data, news, and algorithmic signals."}],education:["Bachelor in Finance, Economics, Accounting, or Math","CFA (Chartered Financial Analyst)","MBA with finance focus","Series 7, 63, 65 licenses"],skills:["Financial modeling","Data analysis","Excel proficiency","Risk management","Communication","Negotiation","Numeracy"],salary:{entry:"$70,000 - $150,000",mid:"$150,000 - $300,000",senior:"$180,000 - $600,000+"},tips:"Master Excel and financial modeling early; pursue CFA Level 1 as an undergrad; intern at banks or funds; build understanding of accounting fundamentals; read financial news daily; understand global markets and economic indicators; network heavily; consider boutique vs. bulge-bracket firm differences.",discussion:["What attracted you to a finance career?","Describe your primary role and day-to-day responsibilities.","How do you approach financial analysis and valuations?","Tell us about a significant transaction or deal.","How has the financial industry evolved?","What are current market dynamics and trends?","How do you manage risk in your work?","What is your investment philosophy?","Tell us about a mentor who shaped your career.","What advice would you give aspiring finance professionals?","How do you navigate market volatility?","What soft skills matter most in finance?","How do you continue learning about markets?"],reflection:["What drives my interest in finance?","How do I view risk and reward?","What financial impact do I want to create?"]},w={title:"Business",overview:"Business spans marketing, operations, supply chain, HR, strategy, and varied company types from startups to Fortune 500s. Career pathways often begin in rotational leadership programs or analyst roles, then specialize. Entrepreneurship demands resilience, design thinking, and financial literacy.",roles:[{title:"Marketing Coordinator",desc:"Supports marketing campaigns by coordinating promotional efforts, managing social media content, and conducting market research."},{title:"Entrepreneur",desc:"An individual who starts, owns, and operates a business venture, often wearing multiple hats across operations, sales, and strategy."},{title:"Consultant",desc:"An expert hired to provide professional advice in areas such as management, marketing, operations, or strategy."},{title:"HR Specialist",desc:"Focuses on recruitment, employee relations, training, benefits administration, or compliance."}],education:["Bachelor in Business Admin or Marketing","MBA","Certificates in Six Sigma, Digital Marketing"],skills:["Strategic planning","Negotiation","Marketing","Project management","Data interpretation"],salary:{entry:"$50,000 - $75,000",mid:"$80,000 - $120,000",senior:"$130,000 - $200,000+"},tips:"Launch micro-venture projects (reselling, tutoring, dropshipping) to learn P&L basics; join Junior Achievement or your campus entrepreneurship club; pitch at local business-plan competitions; take introductory courses in accounting and marketing; attend startup weekends or internships at small businesses where responsibilities are broad.",discussion:["What inspired you to enter the business world?","What is your business focus or industry, and what do you do daily?","What business skills and traits are most valuable?","What was your educational or entrepreneurial journey like?","What resources helped you build your business or career?","Describe a major milestone or setback and how you navigated it.","How do you network and build relationships in your industry?","What are key trends or innovations in your business field?","Who mentored you and helped shape your business mindset?","What advice would you give to aspiring business professionals?","How do you evaluate new opportunities or partnerships?","What are some lessons you have learned from failure?","What advice do you have for building a resilient mindset?"],reflection:["What is your approach to business development?","How do you lead teams through change?","What is your favorite part of your role?"]},b={title:"Education",overview:"Education covers K-12 teaching, higher-ed faculty, instructional design, edtech product, and education policy/administration. Core duties include curriculum design, assessment, and learner engagement. Edtech growth, competency-based learning, and AI-powered tutoring are reshaping educator roles toward facilitation and data-driven personalization.",roles:[{title:"High School Teacher",desc:"Teaches academic subjects to students in grades K-12, develops lesson plans, assesses student progress, and helps prepare students for postsecondary education or careers."},{title:"Instructional Coach",desc:"Supports teachers in improving instructional practices by modeling lessons, analyzing data, and offering feedback."},{title:"Principal",desc:"The head administrator of a school who oversees daily operations, sets academic goals, manages staff, and enforces school policies."},{title:"Curriculum Developer",desc:"Designs, evaluates, and revises instructional materials and standards."}],education:["Bachelor in Education","State Teaching Credential","Master in Education or Administration","Certifications in Special Ed or ESL"],skills:["Classroom management","Curriculum planning","Assessment design","Empathy","Adaptability"],salary:{entry:"$40,000 - $60,000",mid:"$65,000 - $90,000",senior:"$95,000 - $130,000+"},tips:"Tutor peers or younger students; serve as a camp counselor; join Future Educators of America; volunteer with organizations like Khan Academy or Code.org; take child psychology or educational technology electives; pursue instructional-design micro-credentials on Coursera.",discussion:["Why did you choose a career in education?","What grade level or subject do you teach and why?","What is your daily routine as an educator?","What certifications and qualifications are required in education?","What strategies do you use to engage students?","What are the biggest challenges in the education field today?","Describe a rewarding moment in your teaching career.","How do you maintain professional growth as an educator?","Who mentored or inspired you in this career?","What advice would you give to someone considering education as a profession?","How do you foster inclusion and equity in your classroom?","What role does technology play in your teaching methods?","What advice do you have for avoiding burnout in education?"],reflection:["Why did you become a teacher?","How do you handle student challenges?","What keeps you motivated?"]},v={title:"Sports & Athletics",overview:"Beyond professional athletes, the sports industry encompasses sports management, marketing, analytics, sports medicine, coaching, and event operations. Revenue is driven by media rights, sponsorships, and consumer engagement. Data analytics, NIL regulations, and e-sports are growth frontiers.",roles:[{title:"Coach",desc:"Trains and leads athletes or teams in competitive sports. Develops practice plans, teaches techniques and strategies, and fosters teamwork."},{title:"Athletic Trainer",desc:"A certified healthcare professional who prevents, diagnoses, and treats sports-related injuries."},{title:"Sports Analyst",desc:"Evaluates and interprets sports data to provide insights for media coverage, team performance, or fantasy leagues."},{title:"Team Manager",desc:"Responsible for the logistical and administrative operations of a sports team."}],education:["Degree in Kinesiology, Sports Management","Certifications like NASM, CPR, First Aid","Coaching licenses"],skills:["Discipline","Teamwork","Strategic thinking","Physical fitness","Branding"],salary:{entry:"$35,000 - $60,000",mid:"$65,000 - $100,000",senior:"$70,000 - $180,000+"},tips:"Play or volunteer to help manage aspects of a school team; volunteer with local youth leagues; join Sports Analytics Club Program (SACP) or participate in MIT Sloan Sports Analytics Conferences Hackathon; shadow athletic trainers; blog or podcast about sports to build a personal brand; seek game-day operations internships.",discussion:["What led you to a career in the sports industry?","What is your specific role in sports (athlete, coach, management, etc.)?","What does a typical day in your role look like?","What skills and discipline are required for success in sports?","What is your training or educational background?","Describe a defining moment in your sports career.","How do you manage physical and mental wellness?","Who has mentored or coached you throughout your journey?","What are emerging trends or issues in your sports field?","What advice would you give to youth interested in sports careers?","How do you handle high-pressure situations or competition?","What role does teamwork play in your career success?","What life skills has your sports career taught you?"],reflection:["How do you train off-season?","What was your biggest setback?","What is life like beyond the game?"]},k={title:"IT / Engineering",overview:"IT/Engineering integrates hardware, networks, cybersecurity, mechanical, electrical, civil, and systems engineering disciplines that design and sustain the infrastructure behind technology and industry. Growing segments include green energy, smart manufacturing (Industry 4.0), and space tech.",roles:[{title:"Software Engineer",desc:"Designs, develops, tests, and maintains software systems and applications."},{title:"Systems Analyst",desc:"Evaluates and improves computer systems by analyzing user requirements and recommending technology solutions."},{title:"Cybersecurity Expert",desc:"Protects systems, networks, and data from cyber threats. Risk assessment, implementing security protocols, and responding to incidents."},{title:"IT Manager",desc:"Oversees an organizations information technology operations, plans and coordinates IT-related activities, manages staff, and aligns technology strategies with business goals."}],education:["Bachelor in IT or Computer Science","Certifications like CompTIA, CCNA, ITIL","Bachelor in Engineering discipline","PE (Professional Engineer) license"],skills:["Troubleshooting","Customer service","Technical design","Analytical thinking","Math proficiency"],salary:{entry:"$60,000 - $85,000",mid:"$90,000 - $120,000",senior:"$130,000 - $200,000+"},tips:"Join FIRST Robotics, VEX Robotics, or TSA Engineering Design competitions; take calculus, physics, and PLTW courses; attend IEEE, SHPE, NSBE, or SWE high-school outreach events; earn CompTIA A+ or Cisco CCNA for IT fundamentals; intern with a municipal public-works department or local MSP; or build personal projects using Raspberry Pi.",discussion:["What inspired your journey into IT or Engineering?","What are your main responsibilities in your current role?","What tools, platforms, or coding languages do you use?","What educational background or certifications are standard in your field?","Describe a challenging project and how you solved it.","What soft skills are crucial in IT/Engineering roles?","How do you stay current with industry developments?","What are growth opportunities in your sector?","Who mentored you and how did they support your career path?","What advice would you offer to someone new to IT/Engineering?","What projects or innovations are you most excited about?","What advice would you give for passing certifications or exams?","How do you collaborate across teams and departments?"],reflection:["How do you respond to a crisis?","What skills are most in-demand right now?","What is a common misconception about engineering?"]},W={exec:p,tech:m,healthcare:y,legal:g,banking:f,business:w,education:b,sports:v,iteng:k},c=W,A=Object.keys(c),S=A.map(a=>({key:a,pathway:c[a]}));function t(a,e=900,o=480){return`https://images.pexels.com/photos/${a}/pexels-photo-${a}.jpeg?auto=compress&cs=tinysrgb&w=${e}&h=${o}&fit=crop`}function d(a){const e=a.indexOf(". ");return e===-1?a:`${a.slice(0,e)}.`}const C={tech:{name:"Technology",img:36706459},healthcare:{name:"Healthcare",img:6129680},business:{name:"Business",img:3184292},banking:{name:"Banking & Finance",img:7693201},legal:{name:"Legal",img:6077091},iteng:{name:"IT / Engineering",img:89724},education:{name:"Education",img:7972966},sports:{name:"Sports & Athletics",img:5961806},exec:{name:"Executive Leadership",img:7698712}},$=["tech","healthcare","business","banking","legal","iteng","education","sports","exec"];function H(a,e){const o=C[a];return{id:a,name:(o==null?void 0:o.name)??e.title,intro:d(e.overview),description:e.overview,imageUrl:o?t(o.img):null,careers:e.roles.map((n,r)=>({id:`${a}-r${r}`,name:n.title,intro:d(n.desc),description:n.desc,salary:null,imageUrl:null})),salaryByStage:e.salary,skills:e.skills,education:e.education,tip:e.tips,discussion:e.discussion,reflection:e.reflection}}const T=$.map(a=>{const e=S.find(o=>o.key===a);return e?H(a,e.pathway):null}).filter(a=>a!==null),P=[{id:"hr",name:"Human Resources",intro:"Human Resources builds and protects the people side of an organization.",description:"HR hires, develops, and supports employees, and shapes culture, pay, and policy. It sits close to leadership and touches every team — a strong fit for students who are organized, trustworthy, and genuinely care about people.",imageUrl:t(6950031),careers:[{id:"hr-r0",name:"HR Coordinator / Generalist",intro:"The entry point — keeps people processes running.",description:"Supports hiring, onboarding, benefits, and day-to-day employee questions across the HR function.",salary:null,imageUrl:null},{id:"hr-r1",name:"Recruiter / Talent Acquisition",intro:"Finds and hires the right people.",description:"Sources candidates, runs interviews, and partners with managers to fill roles and build teams.",salary:null,imageUrl:null},{id:"hr-r2",name:"HR Business Partner",intro:"Advises a business unit on its people strategy.",description:"A trusted partner to leaders on org design, performance, pay, and tricky employee situations.",salary:null,imageUrl:null},{id:"hr-r3",name:"People Operations / HR Manager",intro:"Owns the systems and team behind HR.",description:"Runs HR programs, tools, and policy, and manages the people team as the organization scales.",salary:null,imageUrl:null}],salaryByStage:{entry:"$45,000 - $65,000",mid:"$70,000 - $110,000",senior:"$120,000 - $200,000+"},skills:["Communication","Empathy & discretion","Conflict resolution","Employment-law basics","HRIS / people data","Organization"],education:["Bachelor in HR, Business, or Psychology","SHRM-CP / PHR certifications","Often entered via a coordinator or recruiting role"],tip:"Get a foothold via a coordinator or recruiting role, learn the employment-law basics early, and remember HR runs on trust and discretion.",discussion:["What led you into human resources?","What part of HR do you work in, and what does a normal day look like?","How does hiring work inside a company, from an open role to someone's first day?","Which skills matter most in HR, and how much of the job is people versus records and data?","What education, certifications, or first jobs are common routes into this field?","How do you handle a difficult conversation between an employee and a manager?","What does discretion mean in HR, and where are its limits?","What advice would you give someone who wants to start in HR?"],reflection:["Who comes to you when they need help, and what do you think makes them trust you?","When people around you disagree, do you step in or stay out of it?","What would make a team or a class feel fair to everyone in it?"]},{id:"comms",name:"Communications",intro:"Communications, Marketing & PR shape how an organization is seen.",description:"This field owns the story, brand, campaigns, and reputation — spanning social media, content, public relations, and brand strategy. It rewards strong writers and creative people who can also read the data.",imageUrl:t(6973351),careers:[{id:"comms-r0",name:"Marketing Coordinator",intro:"The on-ramp into marketing.",description:"Supports campaigns, email, events, and content while learning the channels and tools.",salary:null,imageUrl:null},{id:"comms-r1",name:"Social Media / Content Creator",intro:"Builds the audience and the voice.",description:"Plans, makes, and posts content across platforms and grows the community around a brand.",salary:null,imageUrl:null},{id:"comms-r2",name:"PR / Communications Specialist",intro:"Manages the message and the media.",description:"Writes press materials, builds media relationships, and protects and shapes reputation.",salary:null,imageUrl:null},{id:"comms-r3",name:"Brand / Marketing Manager",intro:"Owns a brand or a marketing area end to end.",description:"Sets strategy, runs campaigns, and measures impact for a product, brand, or audience.",salary:null,imageUrl:null}],salaryByStage:{entry:"$40,000 - $60,000",mid:"$65,000 - $110,000",senior:"$120,000 - $200,000+"},skills:["Writing & storytelling","Social platforms","Analytics","Design sense","Campaign planning","Project management"],education:["Bachelor in Communications, Marketing, or Journalism","A portfolio of real work (posts, campaigns, writing)","Certifications (Google, HubSpot, Meta)"],tip:"Build a portfolio by writing, posting, and running small campaigns now — agency or in-house internships are the usual way in.",discussion:["What pulled you into communications, marketing, or PR?","Which part of the field do you work in, and what does a normal day look like?","How does a campaign come together, from the first idea to the day it goes out?","What separates writing that works from writing people scroll past?","How do you tell whether something you published actually worked?","What do you look for in a portfolio, and does the degree or the work matter more?","What happens when a post or a story gets a bad reaction, and how does the team respond?","What advice would you give someone building an audience or a body of work from nothing?"],reflection:["What is something you wish people understood better, and how would you explain it to them?","Think of an account or a video you keep coming back to. What keeps you there?","What have you made and shared already, even something small, and what did people say about it?"]},{id:"agriculture",name:"Agriculture",intro:"Agriculture is the work of growing, raising, studying, and moving the crops and animals that become food, fiber, and fuel, along with the plants grown in greenhouses and nurseries.",description:"Agriculture covers hands-on production, the science and technology behind it, the business of buying and moving what gets grown, and running an operation. The work happens on row crop and livestock farms, in greenhouses, nurseries, and city farms, at grain elevators, food hubs, and ports, and along the Gulf in rice, sugarcane, and catfish and crawfish ponds. Precision tools have changed the job: soil and water sensors, GPS-guided equipment, and drone imagery are ordinary parts of it now. These four roles are four different ways in, not four rungs in order. A two-year certificate can put you straight into agronomy or precision ag without starting in production first.",imageUrl:t(12387519),careers:[{id:"agriculture-r0",name:"Farmworker / Greenhouse Grower",intro:"Hands-on production work in fields, barns, and greenhouses.",description:"Plants, waters, feeds, and harvests, runs irrigation lines and equipment, and watches crops or animals day to day. It happens on row crop and livestock farms and also in greenhouses, nurseries, and city farms, which are often the versions reachable by bus. Many of these jobs train you on the job and pay from the first week, with no degree needed to start. Some tasks, including running tractors and other machinery, carry minimum ages and a safety certification you take first, so ask an employer what you are cleared to do, and ask whether a job is year-round or seasonal before you count on a yearly figure.",salary:null,imageUrl:null},{id:"agriculture-r1",name:"Agronomist / Precision Ag Technician",intro:"The science and technology side of growing.",description:"Tests soil, scouts fields for pests and disease, reads drone and sensor data, and advises growers on seed, water, and fertilizer. A certificate or two-year associate degree gets people into technician work, and advisory roles usually want a bachelor in agronomy or crop science. Most of this job means driving out to farms, so a driver license matters here.",salary:null,imageUrl:null},{id:"agriculture-r2",name:"Grain Buyer / Agribusiness Sales",intro:"The business and supply side, from the farm gate to the buyer.",description:"Buys, grades, stores, prices, and ships what comes off the farm, and sells seed, feed, and equipment back to growers. These jobs sit at grain elevators, feed and seed dealers, produce distributors, city food hubs, and ports, so some of them are in urban areas. Some start on the driving and warehouse side, where a commercial driver license is the main credential rather than a degree.",salary:null,imageUrl:null},{id:"agriculture-r3",name:"Farm Manager / Owner Operator",intro:"Runs an operation and carries the risk of the season.",description:"Decides what to plant or raise, hires and leads crew, and manages equipment, land, and money. People reach it by working up through production or agronomy, or by starting small with a beginning farmer loan or a land link program that matches new growers with landowners, long before owning any land. Ownership is not a salary: the money moves with yield and prices, and a bad year can pay nothing.",salary:null,imageUrl:null}],salaryByStage:{entry:"$30,000 - $50,000",mid:"$50,000 - $80,000",senior:"$80,000 - $150,000+"},skills:["Working with plants and animals","Machinery operation and repair","Soil, water, and crop data","Safety and hazard awareness","Planning around weather and seasons","Record keeping and budgeting","Practical problem solving"],education:["Paid apprenticeships and on-the-job training, no degree required","Certificate or two-year associate in agriculture, agronomy, or diesel and equipment technology","Bachelor in Agronomy, Animal Science, Agricultural Business, or Agricultural Engineering","Equipment, drone, and applicator certifications earned while working"],tip:"Start with your state's Cooperative Extension service, run through the land grant university in every state and open to anyone, in the city or the country; in Louisiana it is the LSU AgCenter. Its guides are free online, though workshops sometimes charge, so ask the price first. 4-H runs through the county extension office and takes any young person, while FFA runs through schools that offer agriculture classes, so check whether yours does, and ask either one what dues or project costs are before you sign up, since some are waived. For paid work, try a nursery, garden center, feed store, farmers market, or a community or urban farm, and search apprenticeship.gov for farm, equipment, and food jobs near you. Age and safety rules in farm work are different from other jobs and different in every state, so look up your state's youth employment rules and get a work permit if your state uses them before you take anything on. If you want to start something of your own, the USDA Farm Service Agency makes youth loans of up to $5,000 to students for their own farm project, and you apply through a local county office rather than a bank. If drones interest you, the FAA remote pilot study material is free online, but the test is taken in person at a testing center for a fee of around $175, so plan for that cost.",discussion:["What led you into agriculture, and which part of the field do you work in?","What does a typical day look like, and how much does it change from season to season?","What tools or technology do you use now that were not part of this work ten years ago?","Which jobs in this field can someone start without a degree, and what do they pay to start?","What training, licenses, or certifications matter most for the roles you see people hired into?","What are the real safety risks in this work, and how do employers train people for them?","How do people get access to land, equipment, or money when their family does not already have it?","What do people who come into this field from a city or from outside farming usually need to learn first?"],reflection:["Do you want work that keeps you outside and moving, or work that keeps you with data and a screen, or some of both?","How do you feel about work that depends on weather and prices, where a bad year is not your fault but is still your problem?","What do you already know about how food reaches the stores in your neighborhood, and what would you want to find out?"]},{id:"arts",name:"Arts & Entertainment",intro:"Arts and entertainment covers performance and music, film and television, live events, and the design and technical crafts behind them.",description:"Watch the credits on anything and most of the names belong to people you never see on screen: crew, editors, designers, sound and lighting technicians, and the producers and coordinators who hire them. Those roles are more often paid as regular scheduled work than performing is, and several of them can be learned on free software and borrowed equipment. Performing and recording sit in the same industry and pay much less evenly, which is why people often build both at once instead of choosing between them. Where you live matters: film and television production clusters in a few cities, while live events, venues, worship, sports, and corporate video exist in every city. The ranges below assume regular work, which is not how everyone in this field is paid.",imageUrl:t(10809859),careers:[{id:"arts-r0",name:"Set & Stage Crew",intro:"The usual first job on a production, on a set or in a venue.",description:"On film and television the entry title is production assistant. In live events, theaters, and venues it is stagehand or house crew. From there people specialize into a department: camera, grip and electric, sound, lighting, wardrobe, or art. Many production assistant jobs expect a driver's license and a car, because a lot of that work is fetching and delivering. If you do not drive, stage, venue, and live event crew work is the same door without a vehicle.",salary:null,imageUrl:null},{id:"arts-r1",name:"Performer / Musician",intro:"Acting, music, dance, and voice work.",description:"Auditions, rehearses, records, and performs. The free places to build this are school and community theater, choir and church music, open mics, student films, and posting finished work online, none of which need a network to start. Pay arrives unevenly, and it is common to hold other work alongside it, often technical work in the same industry.",salary:null,imageUrl:null},{id:"arts-r2",name:"Editor / Motion Designer",intro:"Puts the finished piece together after the shoot.",description:"Cuts video, lays temporary sound, builds titles and graphics, and finishes the piece an audience actually sees. Sound is a separate craft with its own people, so the real mix goes to a sound editor and mixer. The main editing, color, and graphics programs have free versions that professionals use, and they run on a school or library computer. The work sits at post production houses, studios, networks, and ordinary companies that make their own video, or is done freelance across several clients.",salary:null,imageUrl:null},{id:"arts-r3",name:"Producer / Production Coordinator",intro:"The business and logistics side of getting something made.",description:"Plans schedules and budgets, hires crew and designers, handles permits, contracts, and payroll, and keeps the work on track. The same job runs venues, theaters, festivals, and arts organizations under titles like venue manager, event manager, or arts administrator. It is where set, costume, lighting, and graphic design work gets commissioned, so it is a good seat from which to see every craft in the building.",salary:null,imageUrl:null}],salaryByStage:{entry:"$25,000 - $50,000",mid:"$50,000 - $85,000",senior:"$90,000 - $180,000+"},skills:["Reliability and timekeeping","Teamwork under pressure","Editing and audio software","Practical problem solving","Rehearsal and practice habits","Budgeting and scheduling","Safety on set and stage"],education:["Community college programs in audio, lighting, or media production, usually the lowest cost route, with credits that often transfer. Be careful with private for profit media or recording schools: check accreditation, the total cost, and what graduates actually earn before signing anything.","Stage and production craft apprenticeships where a local offers one, which pay from the first week, charge no tuition, and admit by application rather than by degree. More commonly people work non union or as extra help first and join a local later.","A degree in film, theater, music, design, or arts management, which counts for most in design, producing, and teaching work, and is not required for crew work.","A reel, portfolio, or list of credits, which employers in this field ask to see."],tip:"Start where you already have access: school and community theater crews, a church or venue tech team, student films, choirs, open mics. Those crews are often short of hands and will train you. Learn the tools for free, since the main editing, color, audio, and 3D programs all have free versions professionals use and they run on a school or library computer. If a production comes to your town, ask a teacher, parent, or mentor to help you find out whether they take student helpers, because under 18 you will usually need a work permit and a guardian's signature, and any legitimate production will expect that. Referrals do a lot of the hiring here, so treat every small job as someone remembering your name, and learn what a fair day rate is early, because being new is not a reason to work for free.",discussion:["What led you into arts and entertainment, and what was your first paid job in it?","What does a normal week look like for you, and how much of it is booked in advance?","Which departments do you work with most, and how do people move between them?","How did you learn your craft, and how much of it came from school?","How does someone get hired in your part of the field, and how much of it comes through people who already know your work?","How does pay work for you, and how do you get through slow stretches?","What is the difference between union and non union work where you are, and how did you come to join or not join?","What has changed about the amount and the kind of work available since you started?"],reflection:["Think of something you have watched or listened to more than once. Which part of making it would you have wanted to work on?","When something you worked on is finished, does it matter to you that people know your part in it, or is knowing it yourself enough?","Some jobs in this field pay the same amount every month and some pay per project. Which of those sounds more like the way you would want to work, and what would you want to ask a mentor about it?"]},{id:"community",name:"Community Services",intro:"Community and social services is the paid work of helping people through housing, food, family, health, and school problems.",description:"Community and social services covers case management, youth and family programs, community health, counseling, and the nonprofit and government agencies behind them. Pay is lower than the responsibility deserves, and many entry jobs are hourly or part time, so the yearly number depends as much on hours as on rate. Some doors pay you from the start, including short state certificates such as community health worker, peer support roles built on lived experience rather than a degree, and national service programs that pay a living stipend plus money toward tuition.",imageUrl:t(3958461),careers:[{id:"community-r0",name:"Case Manager",intro:"A common way in, and a job you can be hired into directly.",description:"Works with one person or family at a time: finds out what they need, connects them to housing, food, benefits, or counseling, and keeps a record of what happened. Many case management jobs ask for a bachelor degree; others hire on experience plus training.",salary:null,imageUrl:null},{id:"community-r1",name:"Youth Program Coordinator",intro:"Runs the day to day of a program young people show up to.",description:"Plans activities, supervises staff and volunteers, keeps young people safe, and reports on how the program is going. Coordinators who stay can move up to program manager and then director, running whole programs and the budgets behind them.",salary:null,imageUrl:null},{id:"community-r2",name:"Community Health Worker / Peer Support Specialist",intro:"Paid work built on knowing the community, not on a degree.",description:"Helps neighbors reach care, benefits, and recovery services, often as someone who has been through something similar. In many states these roles are reached through a short state certificate rather than a degree, and the training is sometimes paid for by the employer.",salary:null,imageUrl:null},{id:"community-r3",name:"Social Worker / Counselor",intro:"The licensed side of the field.",description:"Most states license social workers at more than one level, and in many states the title social worker is protected, so you cannot use it without a license: a bachelor in social work leads to the non-clinical license, while clinical practice and therapy need a master degree plus supervised hours after it. Some counseling specialties, including substance use counseling and peer support, are certified rather than licensed and open below a master degree, and for the same work school districts, hospitals, and county or federal agencies usually pay more than small nonprofits.",salary:null,imageUrl:null}],salaryByStage:{entry:"$30,000 - $50,000",mid:"$45,000 - $70,000",senior:"$70,000 - $110,000+"},skills:["Listening","Empathy & boundaries","Clear writing and case notes","De-escalation","Organization & follow-through","Knowing local resources"],education:["Many entry roles hire on a high school diploma plus paid on-the-job training or a short state certificate","Associate degree in human services, or two years at community college and transfer into a bachelor","Bachelor in Social Work for licensed social work; psychology or sociology lead into case management and human services roles","Master degree plus supervised hours for clinical licenses; ask nonprofit and government employers about federal public service loan forgiveness before you borrow"],tip:"Start where your age is already welcome: your school's peer support or mentoring program, a club that runs service projects, and paid summer youth jobs, which many cities use to place teenagers in community organizations. Volunteering helps too, though some places set a minimum age of 16 or 18 for direct contact with people in crisis, so ask what they take at your age and ask them to keep your name for when you reach it. Real contact with people teaches you things a class cannot, and the class is still what gets you hired, so do both.",discussion:["Why did you choose this field, and what keeps you in it?","What does a typical caseload or group of clients look like for you?","What license or certificate does your role require in this state, and how did you earn it?","Which routes into this work do not need a master degree, and how far do they lead?","How did you get your first paid job in this field, and what did it pay?","How do you set boundaries so you can care about people without carrying it all home?","Which employers pay the most in this field, and what do people trade for the pay they take?","What are the biggest challenges facing community and social services right now?"],reflection:["Think of a time someone stepped in for you or for someone you know. What did they actually do that mattered?","When a friend brings you a problem, do you want to fix it, sit with them, or find the person who can help?","What would you want to ask someone doing this work before you spent a year of your life on it?"]},{id:"gov",name:"Government",intro:"Government and public service is the work of running the services a city, a state, or the country provides.",description:"Government and public service covers civil service work at city, state, and federal level, policy and analysis, public administration, and emergency management. Hiring runs on posted announcements, and in many city, county, and state systems on civil service exams, so applications are scored against the criteria in the posting rather than on who you know; it is also slow, and months between applying and hearing back is normal. Career staff are expected to serve the public across changing administrations, so the standard of the job is doing the work well, not taking a side.",imageUrl:t(5613779),careers:[{id:"gov-r0",name:"Administrative / Program Assistant",intro:"The common way into a public agency.",description:"Handles records, permits, scheduling, and questions from the public for a department, and learns how the agency actually runs. In many city, county, and state systems this is the role filled from an eligible list after a civil service exam.",salary:null,imageUrl:null},{id:"gov-r1",name:"Policy Analyst",intro:"Researches a problem and lays out the options.",description:"Gathers data, reads what other places have tried, estimates what each choice would cost, and writes the briefs that department heads and elected officials decide from. Works for a city, a state or federal agency, a legislature, or a research office.",salary:null,imageUrl:null},{id:"gov-r2",name:"Emergency Management Specialist",intro:"Plans for the bad day before it happens.",description:"Builds response plans for storms, fires, outages, and other emergencies, runs drills, and coordinates the fire, police, public health, and utility teams working a live incident. The office may stand on its own or sit inside a fire department or a sheriff's office, depending on the jurisdiction.",salary:null,imageUrl:null},{id:"gov-r3",name:"City Manager / Agency Director",intro:"Runs the day to day operation of a government.",description:"Oversees budgets, staff, and services, and answers to elected officials and to residents. The city manager title exists in cities that use a council-manager form of government; elsewhere the equivalent is an appointed chief administrative officer or a department head.",salary:null,imageUrl:null}],salaryByStage:{entry:"$35,000 - $65,000",mid:"$55,000 - $100,000",senior:"$75,000 - $180,000+"},skills:["Clear writing","Budgets & public data","Working with the public","Speaking a second language","Rules & regulations","Staying calm under pressure","Project coordination"],education:["High school diploma for many entry roles, plus a civil service exam in many city, county, and state systems; federal hiring rates your application and a questionnaire instead of a written entry exam","Associate degree or community college coursework, often transferred into a bachelor's later and often finished part time while already working in an agency","Bachelor in Public Administration, Political Science, Economics, or a related field","Master of Public Administration or Public Policy for many senior and director roles, usually taken part time while employed; some agencies pay part of the cost through tuition assistance, and full time government work is the employment category that qualifies for federal student loan forgiveness, so check the current rules before you borrow"],tip:"Start here: ask your city or county whether it runs a paid summer youth employment program. Some take students at 14 and most at 16, and applications usually open in late winter for the following summer, so ask early and apply the year you become eligible. It will not usually count as qualifying experience on a later announcement, but it shows you how an agency works and gives you a supervisor who can speak for you. Check eligibility before you spend time on an application: most federal jobs require United States citizenship, many public jobs set a minimum age, and some city and county jobs require you to live in the jurisdiction. Most federal openings are posted on one public site, USAJOBS, where you can filter to postings that are open to the public; the Postal Service, the Foreign Service, and the legislative and judicial branches hire through their own sites, and city and county boards mark some postings internal or promotional only. Government pay is public, so a posting usually names a grade and step you can look up on a published salary schedule before you apply, and most public roles add health coverage and a retirement plan on top of that number. Federal emergency management courses are free, online, self paced, and open to anyone, and the introductory ones end in a certificate agencies recognize; many cities and counties also run free community emergency response training. Watch one public meeting with the agenda open, since most city, county, and school board meetings are streamed live or posted as video afterward. Take statistics and civics if your school offers them, and if it does not, a free online course or your library will do the same job, and your own city's budget documents are free practice with real numbers. If you speak another language, put it on every application, because agencies post roles that require it and some pay extra for it.",discussion:["What made you go into public service, and what level of government do you work at?","Walk us through how you were actually hired, from the posting to your first day.","What does a normal week look like, and who do you answer to?","How does a decision move from an idea to something a department actually does?","What happens during budget season in your agency, and what gets decided in it?","How do you keep serving the public well when priorities change with a new administration?","What is a project you worked on that people in your area still use?","What advice would you give someone applying for their first government job?"],reflection:["Think of a service you or your family use, like a bus line, a clinic, a park, or a library. What would you want to fix about the way it works?","If you found out a rule at your school or in your city was affecting some people much worse than others, what would you want to do about it, and who would you need to convince?","A lot of public work is slow and detailed, and the people it helps may never know your name. What kind of work makes you feel the effort was worth it even when nobody says thank you?"]},{id:"science",name:"Science & Research",intro:"Science and research is the work of asking a question carefully and finding out what is actually true.",description:"This field covers laboratory and field research, environmental and climate science, the biological and physical sciences, and the data analysis that turns a study into an answer. It is not the same as technology, where the product is software, or healthcare, where the work is caring for patients. It has more paid entry points than most students are told about, because the labs that run tests, calibrate instruments, and collect samples hire technicians as well as scientists.",imageUrl:t(8442366),careers:[{id:"science-r0",name:"Laboratory Technician",intro:"A common paid entry point into science.",description:"Runs tests, prepares samples, records results, and keeps instruments calibrated and safe. Technicians work in hospital and clinical testing labs, in quality control for water utilities, food, materials, and drug manufacturing, and in university and public agency labs. Often reached with a two-year degree, a technical certificate, or on-the-job training. Lab work in hospitals and clinical testing usually asks for a certification on top of the degree, and some states license the people who run those tests, so ask a specific employer what it requires before you enroll in anything.",salary:null,imageUrl:null},{id:"science-r1",name:"Environmental / Field Scientist",intro:"Science done outdoors, on real sites.",description:"Samples water, soil, and air, surveys habitats, and checks whether a site meets environmental rules. Works for public agencies, consulting firms, utilities, universities, and nonprofits, and the technician version of the job is usually open with a two-year degree. Some jobs at cities and utilities, including water and wastewater treatment, are reached by passing a state operator certification exam rather than by finishing a degree, and the employer often pays for the training and the test. Ask a local water or wastewater utility what its entry grade requires.",salary:null,imageUrl:null},{id:"science-r2",name:"Research Scientist",intro:"Designs the study and answers the question.",description:"Frames a research question, designs experiments or field studies, analyzes what comes back, and writes it up. Works in universities, government labs, hospitals, nonprofits, and company research groups. Usually reached through a graduate degree. Funded PhD programs in the sciences normally pay a stipend and waive tuition, so a PhD is often not paid out of pocket, while a standalone master's is usually the opposite and is normally self-funded. Ask which kind you are being offered before you sign anything.",salary:null,imageUrl:null},{id:"science-r3",name:"Research Data Analyst",intro:"Turns study data into a clear answer.",description:"Cleans, organizes, and analyzes data from experiments, field work, trials, and public health records, then explains what it shows. This sits next to software work, but the goal is the finding, not the product. Often reached with a bachelor in statistics, biology, or a related science, and sometimes from a technician job by learning the analysis tools while working.",salary:null,imageUrl:null}],salaryByStage:{entry:"$35,000 - $60,000",mid:"$55,000 - $105,000",senior:"$90,000 - $160,000+"},skills:["Careful measurement","Lab and field safety","Record keeping","Statistics and data analysis","Scientific writing","Patience with repetition","Asking testable questions"],education:["Associate degree or technical certificate for most technician jobs, and some employers train on the job instead. Registered apprenticeships in some technical and manufacturing fields pay a wage from the first day and the employer covers the classroom instruction, though they are not offered everywhere, so check what exists near you","Bachelor in Biology, Chemistry, Physics, Environmental Science, or Statistics, which many people reach by doing the first two years at a community college and transferring the credits into a four-year school for the last two. Ask both schools which credits transfer before you enroll","PhD for roles that design and lead their own studies, normally funded by a stipend and a tuition waiver rather than paid out of pocket","Master for specialist and lab management roles, usually self-funded, so compare what it costs against what the job it leads to pays"],tip:"If you need to be earning, look for the paid version first. Many cities run a paid summer youth employment program that places teenagers into hospital, university, and public agency jobs, and your school or your library can tell you what your city's is called. Hospitals, universities, utilities, and public agencies also post entry jobs on their own careers pages, so you can apply without anyone introducing you. Many labs set a minimum age of 16 or 18 for safety reasons, so if you are younger, ask what the youngest age they take is and what they would want you to have done by then. Check that a placement is reachable on transit before you accept it. If you have time to give and no paid option yet, a school science club, a science fair project, or a volunteer water test or wildlife count with a local park or river group all count as real experience. Some employers, universities especially, will help pay for a bachelor while you work, so ask about that before you accept a technician job. And if you get to college, ask a science professor in your first year about summer research programs that pay undergraduates a stipend and cover housing, because that is a common route into a funded PhD.",discussion:["What first pulled you into science, and what did your route in actually look like?","What does a normal day look like, and how much of it is at a bench, in the field, or at a computer?","Which jobs on your team are open without a four-year degree, and what do those people do all day?","What certifications or state licences do employers in your area actually ask for?","Who pays for the work you do, and who decides which questions get funded?","What happens when an experiment fails or the data does not support the idea?","How is the work different in a university, a public agency, and a company?","What would you tell a student choosing between a two-year technician program and a four-year degree?"],reflection:["What is something in the natural world you have wondered about and never got a straight answer to?","Think of a time you had to try something several times before it worked. What kept you going, and what would have made it easier?","Would you rather spend most of your day outdoors, at a bench, or with data on a screen? What makes you say that?"]},{id:"trades",name:"Skilled Trades",intro:"The skilled trades are hands-on crafts you can enter through a paid apprenticeship, learning the work on the job while you earn.",description:"Many people enter through a registered apprenticeship, which pays you a wage from the first week and raises it as you pass each stage, or through a one to two year technical program, which can cost very little at a public college and a great deal at a private school, so compare the two before you sign anything. A state or city license stays with you rather than with one employer, though welding works differently, because welding qualifications are tied to a shop's own procedures and usually mean testing again when you change companies. Electrical and mechanical apprenticeships have run in Chicago for a long time, and industrial welding and pipefitting are steady work along the Gulf Coast corridor.",imageUrl:t(14319099),careers:[{id:"trades-r0",name:"Electrician",intro:"Installs and maintains the wiring and power systems people depend on.",description:"Installs and maintains wiring, panels, and power systems in homes, buildings, and industrial plants, working from drawings and to code. Entered through a paid apprenticeship, and licensed at the state or city level depending on where you work, usually at a journeyman level first and a master level later.",salary:null,imageUrl:null},{id:"trades-r1",name:"HVAC/R Technician",intro:"Keeps heating, cooling, and refrigeration systems running.",description:"Installs, services, and repairs heating, air conditioning, and refrigeration systems in homes, offices, and food and cold storage sites. Handling refrigerants requires a federal certification, which you take during training, and the work runs through both seasons because something needs fixing in each of them.",salary:null,imageUrl:null},{id:"trades-r2",name:"Welder / Pipefitter",intro:"Joins metal and builds the piping systems inside plants and buildings.",description:"Welders join metal to a set procedure and to a standard an inspector can check. Pipefitters lay out, fit, and install piping in plants, ships, and buildings, often alongside welders. Pay follows tested welding qualifications, which you earn by passing a weld test on a shop's own procedure, so expect to test again when you move to a new company.",salary:null,imageUrl:null},{id:"trades-r3",name:"Construction Superintendent / Foreman",intro:"Leads the work on site and keeps the job on schedule.",description:"A foreman runs one crew inside one trade. A superintendent runs the whole site, sequencing the trades, ordering materials, holding the schedule, and answering to the owner. One common route up is out of a craft, so this rung often starts on the tools, and others come in through a construction management program.",salary:null,imageUrl:null}],salaryByStage:{entry:"$30,000 - $55,000",mid:"$55,000 - $110,000",senior:"$100,000 - $200,000+"},skills:["Blueprint and spec reading","Measurement and shop math","Troubleshooting","Hand and power tools","Job site safety","Working to a schedule","Working on a crew"],education:["Registered apprenticeship, usually three to five years, paid from the first week; ask each program what the classroom part costs, because that varies","Technical certificate under a year, or a two-year associate degree, at a public community or technical college; compare the cost against a paid apprenticeship before you borrow for a private school","State or city license depending on where you work, usually journeyman first and master later","Trade certifications, such as a federal refrigerant certification for HVAC/R or a passed weld test for welding"],tip:"Registered apprenticeships usually start at 18, so between 14 and 17 the move is the on-ramp: take shop, welding, drafting, or a CTE or dual-credit class at school, and look for a pre-apprenticeship, asking each one what age it takes and whether it pays you while you train. You do not need a contact in the industry to find these, because a shop or CTE teacher, your school counselor, your local workforce board, or the Department of Labor apprenticeship finder will all point you at registered programs, and some pre-apprenticeships are built specifically for women entering the trades and are usually free like the rest. When you do apply, apply to both union locals and contractor associations, since both pay you from the first week, and ask each one directly what the classroom part costs. Expect to bring your own boots and a starter set of hand tools, so ask what a program expects on day one, because some supply them and some help you get them, and ask whether your school or workforce board runs the entry-level construction safety card for free before you pay for one online. Crews work to a fixed schedule and the whole job waits on whoever is late, so being on time is part of the craft here rather than a personality trait.",discussion:["What led you into your trade, and what did the first year of it look like?","How did you get in, and what does a registered apprenticeship ask of someone day to day?","What license or certification does this trade require where you work, and how do you keep it current?","What does a normal day on the job look like, from the first hour to the last?","How does pay move as someone goes from apprentice to journeyman and beyond?","What does this work ask of your body over the years, and how do people in the trade protect themselves?","What are the routes up from the tools, into leading a crew, running a site, or owning a shop?","How is the work changing, and what should someone starting now learn early?"],reflection:["What is something you have taken apart, built, or fixed, even if it did not work out?","Does it matter to you whether you can point at what you finished at the end of the day?","Does it matter to you whether your training pays you while you do it?"]}],u=[...T,...P];function x(a){return u.find(e=>e.id===a)}const j="business",E={technology:"tech","science and research":"science","health & medicine":"healthcare",healthcare:"healthcare",law:"legal",government:"gov",business:"business","commerce & retail":"business",communications:"comms","arts & entertainment":"arts","education or academia":"education",education:"education",athletics:"sports","community & social services":"community",agriculture:"agriculture"};function M(a){return[a.name,...a.careers.map(e=>e.name),...a.skills??[]].join(" ").toLowerCase().split(/[^a-z]+/).filter(e=>e.length>3)}function R(a,e){if(e){const i=E[e.trim().toLowerCase()];if(i)return i}const o=(a??"").toLowerCase();let n=j,r=0;for(const i of u){const s=M(i).reduce((l,h)=>o.includes(h)?l+1:l,0);s>r&&(r=s,n=i.id)}return n}export{j as D,u as a,x as f,R as g};
